Version-specific facts should name the version. The `@static if VERSION` gate makes the branch disappear at compile time, and the comment tells the editor when it can be deleted.

```julia
using OffsetArrays

function chunks(v::AbstractVector, n::Integer)
    n >= 1 || throw(ArgumentError("chunk size must be at least 1, got $n"))
    return Iterators.partition(v, n)
end

# Checks
v = collect(1:7)
cs = collect(chunks(v, 3))
v[1] = 100

o = OffsetArray(collect(1:7), -3:3)
@assert collect(chunks(o, 3)) == [[1, 2, 3], [4, 5, 6], [7]]
