function divisor_sum(n::Integer)
    n >= 1 || throw(ArgumentError("n must be positive"))
    s = zero(n)
    for d in 1:isqrt(n)
        q, r = divrem(n, d)
        r == 0 || continue
        s += d
        q != d && (s += q)
    end
    return s
end

is_perfect(n::Integer) = n > 1 && divisor_sum(n) == 2n

# Checks
@assert is_perfect(6) && is_perfect(28) && is_perfect(496)
@assert !is_perfect(1) && !is_perfect(12)
@assert filter(is_perfect, 1:10000) == [6, 28, 496, 8128]
@assert divisor_sum(36) == 91
```

Divisors come in pairs `(d, n/d)`, so scanning only up to `isqrt(n)` finds all of them in O(sqrt n); the `q != d` test avoids double-counting a square root. A perfect number's divisor sum, including itself, is exactly 2n.

