function merge_sorted(a::AbstractVector, b::AbstractVector)
    out = Vector{promote_type(eltype(a), eltype(b))}(undef, length(a) + length(b))
    i, j = firstindex(a), firstindex(b)
    for k in eachindex(out)
        if j > lastindex(b) || (i <= lastindex(a) && !isless(b[j], a[i]))
            out[k] = a[i]; i += 1
        else
            out[k] = b[j]; j += 1
        end
    end
    return out
end

