```julia
function edit_distance(a::AbstractString, b::AbstractString)
    s, t = collect(a), collect(b)
    length(t) > length(s) && ((s, t) = (t, s))   # t is the shorter one
    prev = collect(0:length(t))
    cur = similar(prev)
    for i in eachindex(s)
        cur[1] = i
        for j in eachindex(t)
            cost = s[i] == t[j] ? 0 : 1
            cur[j+1] = min(prev[j+1] + 1, cur[j] + 1, prev[j] + cost)
        end
        prev, cur = cur, prev
    end
    return prev[end]
end

# Checks
@assert edit_distance("kitten", "sitting") == 3
@assert edit_distance("same", "same") == 0
@assert edit_distance("flaw", "lawn") == 2
@assert edit_distance("café", "cafe") == 1
```

Each cell depends only on the previous row and the cell to its left, so two vectors replace the full table and the shorter string sets their length. Insert, delete, and substitute all cost 1. Work is O(mn) time; collecting to `Char` vectors makes `é` count as a single edit.

```julia
function balanced(s::AbstractString)
    pairs_ = Dict(')' => '(', ']' => '[', '}' => '{')
    stack = Char[]
    for c in s
        if c in values(pairs_)
            push!(stack, c)
        elseif haskey(pairs_, c)
            (!isempty(stack) && pop!(stack) == pairs_[c]) || return false
        end
    end
    return isempty(stack)
end

# Checks
@assert balanced("([]{})")
@assert balanced("f(x[i]) { return 1; }")
@assert !balanced("(]")
@assert !balanced("(()")
```

A stack of open brackets is the natural structure: every closer must match the most recent unmatched opener, and the stack must be empty at the end. Non-bracket characters are ignored. The check is O(n); `pop!(stack)` is guarded by the `isempty` test so a stray closer returns `false` rather than throwing.

