function stable_norm(x::AbstractVector{<:Real})
    isempty(x) && return zero(float(eltype(x)))
    m = maximum(abs, x)
    iszero(m) && return zero(float(m))
    return m * sqrt(sum(v -> (v / m)^2, x))
end

