```julia
function ellipsize(s::AbstractString, n::Integer)
    n >= 1 || throw(ArgumentError("n must be at least 1, got $n"))
    length(s) <= n && return String(s)
    return first(s, n - 1) * "…"
end

# Checks
@assert ellipsize("hello", 10) == "hello"
@assert ellipsize("hello world", 6) == "hello…"
@assert ncodeunits(ellipsize("日本語のテキスト", 4)) == 12   # bytes differ from characters

err = try ellipsize("abc", 0); nothing catch e; e end
@assert err isa ArgumentError && occursin("at least 1", err.msg)
```

`first(s, k)` for a string takes `k` characters, not bytes, so it never cuts inside a multibyte character; `s[1:k]` would raise `StringIndexError` or cut at the wrong place. `length` counts characters (Unicode code points) and `ncodeunits` counts bytes. A code point is still not always what a reader sees as one character: for combining accents or flag emoji, count `Unicode.graphemes(s)` instead.

```julia
function moving_average(x::AbstractVector{<:Real}, k::Integer)
    1 <= k <= length(x) || throw(ArgumentError("window k = $k must be in 1:$(length(x))"))
    c = cumsum(x)
    pushfirst!(c, zero(eltype(c)))
    return [(c[i+k] - c[i]) / k for i in 1:length(x)-k+1]
end

# Checks
@assert moving_average([1, 2, 3, 4, 5], 2) == [1.5, 2.5, 3.5, 4.5]
@assert moving_average([4, 4, 4, 4], 1) == [4.0, 4.0, 4.0, 4.0]
@assert length(moving_average(rand(100), 10)) == 91
@assert try moving_average([1, 2], 3); false catch e; e isa ArgumentError end
```

Differences of the cumulative sum give every window sum in O(n) total, rather than O(nk) for re-summing. The leading zero in `c` lets the first window use the same formula. For floating-point data over very long series, cumulative sums lose some precision compared to summing each window directly.

